import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type BusinessHealthBuilderProps = Record<string, any>;

const BusinessHealthBuilder: React.FC<BusinessHealthBuilderProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 8,
  leftText = "BUSINESS",
  rightText = "HEALTH",
  globalScale = 1,
  offsetX = 0,
  offsetY = 0,
  figureColor = "#f8fafc",
  leftSculptureColor = "#38bdf8",
  rightSculptureColor = "#4ade80",
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const totalFrames = durationInSeconds * fps;

  // Timeline Markers
  const t1 = totalFrames * 0.1;
  const t2 = totalFrames * 0.2;
  const t3 = totalFrames * 0.45;
  const t4 = totalFrames * 0.55;
  const t5 = totalFrames * 0.65;
  const t6 = totalFrames * 0.9;
  const t7 = totalFrames * 0.95;

  // Layout Boundaries
  const baseX = width / 2;
  const groundY = height * 0.8; 
  const leftTargetOffset = -width * 0.25;
  const rightTargetOffset = width * 0.25;

  // X Position Interpolation (Strictly Monotonic)
  const charXOffset = interpolate(
    frame,
    [t1, t2, t4, t5, t6, t7],
    [0, leftTargetOffset, leftTargetOffset, rightTargetOffset, rightTargetOffset, 0],
    { easing: Easing.inOut(Easing.quad), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Arm Chopping Logic (Using cosine to ensure it starts exactly at 0 to prevent popping)
  const isBuildingL = frame >= t2 && frame <= t3;
  const isBuildingR = frame >= t5 && frame <= t6;

  const leftArmRotation = isBuildingL
    ? 35 * Math.cos((frame - t2) * 0.6) - 35
    : 0;

  const rightArmRotation = isBuildingR
    ? -35 * Math.cos((frame - t5) * 0.6) + 35
    : 0;

  // Dynamic Typography Scaling
  const maxChars = Math.max(1, leftText.length, rightText.length);
  const maxTowerHeight = height * 0.55;
  const blockGap = 6;
  const blockSize = Math.min(140, (maxTowerHeight / maxChars) - blockGap);

  // Shared Block Render Logic
  const renderTower = (
    text: string, 
    color: string, 
    xOffset: number, 
    startTime: number, 
    endTime: number
  ) => {
    const letters = text.toUpperCase().split('');
    const DROP_FRAMES = 15;
    const buildAvailable = Math.max(1, (endTime - startTime) - DROP_FRAMES);
    const delayPerLetter = buildAvailable / Math.max(1, letters.length - 1);

    return (
      <div style={{
        position: "absolute",
        left: baseX + xOffset,
        bottom: height - groundY + 10, // 10px buffer from line
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: `${blockGap}px`,
        transform: "translateX(-50%)",
        transition: "none"
      }}>
        {letters.map((char, i) => {
          const reverseIndex = letters.length - 1 - i;
          const letterStart = startTime + reverseIndex * delayPerLetter;
          
          const dropProgress = interpolate(
            frame, 
            [letterStart, letterStart + DROP_FRAMES], 
            [0, 1], 
            { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.back(1.5)) }
          );

          const yOff = interpolate(dropProgress, [0, 1], [-height * 0.6, 0]);
          const opac = interpolate(dropProgress, [0, 0.2], [0, 1], { extrapolateRight: "clamp" });
          const scale = interpolate(dropProgress, [0, 0.5, 1], [0.5, 1.1, 1], { extrapolateRight: "clamp" });
          const rotate = interpolate(dropProgress, [0, 1], [i % 2 === 0 ? 15 : -15, 0], { extrapolateRight: "clamp" });

          return (
            <div key={`${text}-${i}`} style={{
              backgroundColor: color,
              color: backgroundColor,
              width: blockSize,
              height: blockSize,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              borderRadius: blockSize * 0.15,
              fontWeight: 900,
              fontSize: blockSize * 0.6,
              opacity: opac,
              transform: `translateY(${yOff}px) rotate(${rotate}deg) scale(${scale})`,
              boxShadow: `0px ${blockSize * 0.1}px ${blockSize * 0.2}px rgba(0,0,0,0.4)`,
              transition: "none",
              willChange: "transform, opacity"
            }}>
              {char}
            </div>
          )
        })}
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Montserrat", overflow: "hidden" }}>
      <div style={{
        width: "100%",
        height: "100%",
        transform: `translate(${offsetX}px, ${offsetY}px) scale(${globalScale})`,
        transformOrigin: "center center",
        position: "relative",
        transition: "none"
      }}>
        
        {/* Ground Line */}
        <div style={{
          position: "absolute",
          top: groundY,
          left: "5%",
          width: "90%",
          height: "6px",
          backgroundColor: figureColor,
          opacity: 0.3,
          borderRadius: 3,
          transition: "none"
        }} />

        {/* Left Sculpture */}
        {renderTower(leftText, leftSculptureColor, leftTargetOffset - width * 0.1, t2, t3)}

        {/* Right Sculpture */}
        {renderTower(rightText, rightSculptureColor, rightTargetOffset + width * 0.1, t5, t6)}

        {/* Stick Figure Container */}
        <div style={{
          position: "absolute",
          top: groundY - 200, 
          left: baseX + charXOffset - 50, 
          width: 100,
          height: 200,
          transition: "none",
          willChange: "transform, left"
        }}>
          <svg width="100" height="200" viewBox="0 0 100 200" style={{ overflow: "visible", transition: "none" }}>
            {/* Head */}
            <circle cx="50" cy="30" r="20" fill={backgroundColor} stroke={figureColor} strokeWidth="8" style={{ transition: "none" }} />
            
            {/* Body */}
            <line x1="50" y1="50" x2="50" y2="130" stroke={figureColor} strokeWidth="8" strokeLinecap="round" style={{ transition: "none" }} />
            
            {/* Left Leg */}
            <line x1="50" y1="130" x2="15" y2="195" stroke={figureColor} strokeWidth="8" strokeLinecap="round" style={{ transition: "none" }} />
            
            {/* Right Leg */}
            <line x1="50" y1="130" x2="85" y2="195" stroke={figureColor} strokeWidth="8" strokeLinecap="round" style={{ transition: "none" }} />

            {/* Left Arm (Viewer's left) */}
            <g transform={`translate(50, 70) rotate(${leftArmRotation})`} style={{ transition: "none", willChange: "transform" }}>
              <line x1="0" y1="0" x2="-40" y2="40" stroke={figureColor} strokeWidth="8" strokeLinecap="round" style={{ transition: "none" }} />
            </g>

            {/* Right Arm (Viewer's right) */}
            <g transform={`translate(50, 70) rotate(${rightArmRotation})`} style={{ transition: "none", willChange: "transform" }}>
              <line x1="0" y1="0" x2="40" y2="40" stroke={figureColor} strokeWidth="8" strokeLinecap="round" style={{ transition: "none" }} />
            </g>
          </svg>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default BusinessHealthBuilder;